// Bake the MAVLink msgid table (crc_extra, min_payload_len, target field
// offsets) at compile time from the vendored dialect XML.
//
// `crc_extra.rs` is `include!`d at the top of this file so that
// `crc_extra_for_message` (the runtime crate's single source of truth) is also
// what runs here — there is no second implementation to drift.
//
// Output is one generated file in `$OUT_DIR/generated_msgid_table.rs`
// containing `pub(crate) const SORTED: &[(u32, MsgEntry)]` (sorted by msgid),
// included from `src/mavlink/generated.rs`.

include!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/src/mavlink/crc_extra.rs"
));

use std::collections::{HashMap, HashSet};
use std::fs;
use std::io::Write;
use std::path::{Path, PathBuf};

use quick_xml::Reader;
use quick_xml::events::{BytesStart, Event};

const DIALECTS: &[&str] = &["common.xml", "ardupilotmega.xml"];

#[derive(Debug)]
struct ParsedField {
    name: String,
    type_name: String,
    array_length: u8,
    is_extension: bool,
}

#[derive(Debug)]
struct ParsedMessage {
    id: u32,
    name: String,
    fields: Vec<ParsedField>,
}

#[derive(Debug, Clone)]
struct MsgEntryGen {
    name: String,
    crc_extra: u8,
    min_payload_len: u16,
    target_sys_offset: Option<u16>,
    target_comp_offset: Option<u16>,
}

fn main() {
    println!("cargo:rerun-if-changed=build.rs");
    println!("cargo:rerun-if-changed=src/mavlink/crc_extra.rs");

    let xml_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("vendor")
        .join("mavlink");

    let mut entries: HashMap<u32, MsgEntryGen> = HashMap::new();
    let mut visited: HashSet<PathBuf> = HashSet::new();
    let mut in_progress: HashSet<PathBuf> = HashSet::new();

    for dialect in DIALECTS {
        let p = xml_dir.join(dialect);
        process_xml(&p, &mut entries, &mut visited, &mut in_progress);
    }

    if entries.is_empty() {
        panic!("no MAVLink messages parsed from vendored dialects");
    }
    if !entries.contains_key(&0) {
        panic!("HEARTBEAT (id 0) not found — vendored XML appears incomplete");
    }

    let mut sorted: Vec<(u32, MsgEntryGen)> = entries.into_iter().collect();
    sorted.sort_by_key(|(id, _)| *id);

    let out_dir = std::env::var("OUT_DIR").expect("OUT_DIR not set by cargo");
    let out_path = PathBuf::from(&out_dir).join("generated_msgid_table.rs");
    let mut out = std::io::BufWriter::new(fs::File::create(&out_path).unwrap_or_else(|e| {
        panic!("create {}: {}", out_path.display(), e);
    }));

    writeln!(
        out,
        "// generated by build.rs from {DIALECTS:?} — do not edit"
    )
    .unwrap();
    writeln!(out, "pub(crate) const SORTED: &[(u32, MsgEntry)] = &[").unwrap();
    for (id, e) in &sorted {
        writeln!(
            out,
            "    ({id}, MsgEntry {{ name: {name:?}, crc_extra: {crc}, min_payload_len: {mpl}, target_sys_offset: {ts:?}, target_comp_offset: {tc:?} }}),",
            id = id,
            name = e.name,
            crc = e.crc_extra,
            mpl = e.min_payload_len,
            ts = e.target_sys_offset,
            tc = e.target_comp_offset,
        )
        .unwrap();
    }
    writeln!(out, "];").unwrap();
}

fn process_xml(
    path: &Path,
    entries: &mut HashMap<u32, MsgEntryGen>,
    visited: &mut HashSet<PathBuf>,
    in_progress: &mut HashSet<PathBuf>,
) {
    let canon = fs::canonicalize(path)
        .unwrap_or_else(|e| panic!("dialect XML not found: {} ({})", path.display(), e));

    if in_progress.contains(&canon) {
        panic!("cycle in <include> resolution at {}", canon.display());
    }
    if !visited.insert(canon.clone()) {
        return;
    }
    in_progress.insert(canon.clone());
    println!("cargo:rerun-if-changed={}", canon.display());

    let content =
        fs::read_to_string(&canon).unwrap_or_else(|e| panic!("read {}: {}", canon.display(), e));
    let (includes, messages) = parse_xml(&content);

    let dir = canon.parent().expect("XML has a parent dir").to_path_buf();
    for inc in includes {
        let inc_path = dir.join(&inc);
        process_xml(&inc_path, entries, visited, in_progress);
    }

    for msg in messages {
        let crc_fields: Vec<CrcExtraField<'_>> = msg
            .fields
            .iter()
            .map(|f| CrcExtraField {
                name: &f.name,
                type_name: &f.type_name,
                array_length: f.array_length,
                is_extension: f.is_extension,
            })
            .collect();
        let crc_extra = crc_extra_for_message(&msg.name, &crc_fields);
        let (min_payload_len, target_sys_offset, target_comp_offset) = compute_offsets(&msg.fields);

        if let Some(prev) = entries.get(&msg.id) {
            if prev.crc_extra != crc_extra {
                panic!(
                    "crc_extra conflict for msgid {} ({} vs {} in {}): {} != {}",
                    msg.id,
                    prev.name,
                    msg.name,
                    canon.display(),
                    prev.crc_extra,
                    crc_extra
                );
            }
            if prev.name != msg.name {
                panic!(
                    "msgid {} declared under two names: '{}' and '{}' (in {})",
                    msg.id,
                    prev.name,
                    msg.name,
                    canon.display()
                );
            }
            continue;
        }
        entries.insert(
            msg.id,
            MsgEntryGen {
                name: msg.name,
                crc_extra,
                min_payload_len,
                target_sys_offset,
                target_comp_offset,
            },
        );
    }

    in_progress.remove(&canon);
}

fn parse_xml(content: &str) -> (Vec<String>, Vec<ParsedMessage>) {
    let mut reader = Reader::from_str(content);
    reader.config_mut().trim_text(true);

    let mut includes = Vec::new();
    let mut messages = Vec::new();

    let mut in_include = false;
    let mut current_msg: Option<ParsedMessage> = None;
    let mut past_extensions = false;

    loop {
        match reader.read_event() {
            Ok(Event::Start(e)) => {
                let tag = std::str::from_utf8(e.name().as_ref())
                    .expect("tag name not utf8")
                    .to_string();
                match tag.as_str() {
                    "include" => in_include = true,
                    "message" => {
                        let (id, name) = parse_msg_attrs(&e);
                        current_msg = Some(ParsedMessage {
                            id,
                            name,
                            fields: Vec::new(),
                        });
                        past_extensions = false;
                    }
                    "extensions" => {
                        if current_msg.is_some() {
                            past_extensions = true;
                        }
                    }
                    "field" => {
                        if let Some(msg) = current_msg.as_mut() {
                            let (type_name, field_name) = parse_field_attrs(&e);
                            let (elem, len) = parse_array_suffix(&type_name);
                            msg.fields.push(ParsedField {
                                name: field_name,
                                type_name: elem,
                                array_length: len,
                                is_extension: past_extensions,
                            });
                        }
                    }
                    _ => {}
                }
            }
            Ok(Event::Empty(e)) => {
                let tag = std::str::from_utf8(e.name().as_ref())
                    .expect("tag name not utf8")
                    .to_string();
                match tag.as_str() {
                    "extensions" => {
                        if current_msg.is_some() {
                            past_extensions = true;
                        }
                    }
                    "field" => {
                        if let Some(msg) = current_msg.as_mut() {
                            let (type_name, field_name) = parse_field_attrs(&e);
                            let (elem, len) = parse_array_suffix(&type_name);
                            msg.fields.push(ParsedField {
                                name: field_name,
                                type_name: elem,
                                array_length: len,
                                is_extension: past_extensions,
                            });
                        }
                    }
                    _ => {}
                }
            }
            Ok(Event::Text(e)) => {
                if in_include {
                    let text = e.unescape().expect("text unescape").trim().to_string();
                    if !text.is_empty() {
                        includes.push(text);
                    }
                }
            }
            Ok(Event::End(e)) => {
                let tag = std::str::from_utf8(e.name().as_ref())
                    .expect("tag name not utf8")
                    .to_string();
                match tag.as_str() {
                    "include" => in_include = false,
                    "message" => {
                        if let Some(msg) = current_msg.take() {
                            messages.push(msg);
                        }
                    }
                    _ => {}
                }
            }
            Ok(Event::Eof) => break,
            Err(e) => panic!("XML parse error: {e}"),
            _ => {}
        }
    }

    (includes, messages)
}

fn parse_msg_attrs(e: &BytesStart<'_>) -> (u32, String) {
    let mut id = 0u32;
    let mut name = String::new();
    for attr_res in e.attributes() {
        let attr = attr_res.expect("attribute parse failed");
        let key = std::str::from_utf8(attr.key.as_ref()).expect("attr key utf8");
        let val = attr.unescape_value().expect("attr value unescape");
        match key {
            "id" => {
                id = val
                    .trim()
                    .parse()
                    .unwrap_or_else(|e| panic!("bad message id '{val}': {e}"));
            }
            "name" => name = val.into_owned(),
            _ => {}
        }
    }
    (id, name)
}

fn parse_field_attrs(e: &BytesStart<'_>) -> (String, String) {
    let mut type_name = String::new();
    let mut field_name = String::new();
    for attr_res in e.attributes() {
        let attr = attr_res.expect("attribute parse failed");
        let key = std::str::from_utf8(attr.key.as_ref()).expect("attr key utf8");
        let val = attr.unescape_value().expect("attr value unescape");
        match key {
            "type" => type_name = val.into_owned(),
            "name" => field_name = val.into_owned(),
            _ => {}
        }
    }
    (type_name, field_name)
}

fn parse_array_suffix(t: &str) -> (String, u8) {
    if let Some(lb) = t.find('[') {
        let rb = t
            .find(']')
            .unwrap_or_else(|| panic!("malformed array type '{t}'"));
        let elem = t[..lb].to_string();
        let len: u8 = t[lb + 1..rb]
            .parse()
            .unwrap_or_else(|_| panic!("bad array length in '{t}'"));
        if len == 0 {
            panic!("zero-length array in '{t}'");
        }
        (elem, len)
    } else {
        (t.to_string(), 0)
    }
}

fn compute_offsets(fields: &[ParsedField]) -> (u16, Option<u16>, Option<u16>) {
    let mut base: Vec<&ParsedField> = fields.iter().filter(|f| !f.is_extension).collect();
    base.sort_by(|a, b| type_size(&b.type_name).cmp(&type_size(&a.type_name)));

    let mut off: u16 = 0;
    let mut tsys = None;
    let mut tcomp = None;
    for f in &base {
        if f.array_length == 0 && f.type_name == "uint8_t" {
            if f.name == "target_system" {
                tsys = Some(off);
            } else if f.name == "target_component" {
                tcomp = Some(off);
            }
        }
        let elem = type_size(&f.type_name) as u16;
        let n = if f.array_length == 0 {
            1u16
        } else {
            f.array_length as u16
        };
        off = off
            .checked_add(elem * n)
            .unwrap_or_else(|| panic!("payload overflow for field '{}'", f.name));
    }
    (off, tsys, tcomp)
}
